provider.example:
monaco.languages.registerHoverProvider('javascript', {
  provideHover(model, position, token, context) {
    const word = model.getWordAtPosition(position)
    if (!word) return null

    // Optional: honour a verbosity request from the hover widget
    const delta = context?.verbosityRequest?.verbosityDelta ?? 0

    return {
      contents: [
        {
          value: '**console**\n\nProvides access to the debugging console.',
          isTrusted: true,
          supportThemeIcons: true,
        }
      ],
      range: {
        startLineNumber: position.lineNumber,
        endLineNumber:   position.lineNumber,
        startColumn:     word.startColumn,
        endColumn:       word.endColumn,
      },
      canIncreaseVerbosity: delta < 1,
      canDecreaseVerbosity: delta > 0,
    }
  }
})

monaco.languages.registerDefinitionProvider('typescript', {
  provideDefinition(model, position, token) {
    const word = model.getWordAtPosition(position)
    if (!word) return null

    // (a) Single Location
    return {
      uri: monaco.Uri.parse('file:///src/utils.ts'),
      range: {
        startLineNumber: 42, startColumn: 1,
        endLineNumber:   42, endColumn:   20,
      }
    }
  }
})

// (b) LocationLink[] — richer peek/Ctrl+click experience.
//     NOTE the field names: uri + range (NOT targetUri/targetRange).
monaco.languages.registerDefinitionProvider('typescript', {
  provideDefinition(model, position) {
    const word = model.getWordAtPosition(position)
    if (!word) return null

    return [{
      originSelectionRange: {
        startLineNumber: position.lineNumber, startColumn: word.startColumn,
        endLineNumber:   position.lineNumber, endColumn:   word.endColumn,
      },
      uri: monaco.Uri.parse('file:///src/utils.ts'),
      range: {                       // full target range e.g. whole function
        startLineNumber: 42, startColumn: 1,
        endLineNumber:   50, endColumn:   1,
      },
      targetSelectionRange: {        // just the symbol name; must sit inside range
        startLineNumber: 42, startColumn: 10,
        endLineNumber:   42, endColumn:   20,
      },
    }]
  }
})

monaco.languages.registerCompletionItemProvider('typescript', {
  triggerCharacters: ['.', '"', "'", '/'],

  provideCompletionItems(model, position, context, token) {
    const word  = model.getWordUntilPosition(position)
    const range = {
      startLineNumber: position.lineNumber,
      endLineNumber:   position.lineNumber,
      startColumn:     word.startColumn,
      endColumn:       word.endColumn,
    }

    if (token.isCancellationRequested) return { suggestions: [] }

    return {
      incomplete: false,
      suggestions: [
        // Snippet — kind 28, NOT 15
        {
          label:           'fn',
          kind:            28,   // CompletionItemKind.Snippet
          insertText:      'function ${1:name}(${2:params}): ${3:void} {\n\t$0\n}',
          insertTextRules: 4,    // InsertAsSnippet
          documentation:   { value: '**function** snippet\n\nInserts a typed function declaration' },
          detail:          'snippet',
          range,
        },
        // Keyword — kind 17, NOT 14
        {
          label:           'interface',
          kind:            17,   // CompletionItemKind.Keyword
          insertText:      'interface ${1:Name} {\n\t$0\n}',
          insertTextRules: 4,
          documentation:   'Declare a TypeScript interface',
          detail:          'keyword',
          range,
        },
        // Function — kind 1
        {
          label:           'console.log',
          kind:            1,    // CompletionItemKind.Function
          insertText:      'console.log(${1:value})',
          insertTextRules: 4,
          documentation:   { value: '**console.log**(value: any)\n\nLogs to the console' },
          detail:          'built-in',
          preselect:       true,
          range,
        },
        // Rich label + deprecation tag
        {
          label: {
            label:       'useState',
            detail:      '<S>(initialState: S)',
            description: 'react',
          },
          kind:            1,
          tags:            [],   // [1] would render a strikeout (Deprecated)
          insertText:      'const [${1:state}, ${2:setState}] = useState<${3:T}>(${4:initial})',
          insertTextRules: 4,
          documentation:   { value: '**useState**\n\nReact state hook' },
          detail:          'hook',
          range,
        },
        // Separate insert/replace ranges (CompletionItemRanges)
        {
          label:      'toString',
          kind:       0,         // CompletionItemKind.Method
          insertText: 'toString()',
          range:      { insert: range, replace: range },
        },
      ]
    }
  },

  // Lazily attach docs when the item gains focus
  resolveCompletionItem(item, token) {
    return { ...item, documentation: { value: 'Detailed docs' } }
  }
})
